TALLAS_M = ['36', '36.5', '37', '37.5', '38', '38.5', '39', '40']

# Vistas de las zapatillas (todas las fotos muestran el par): par completo, zapatilla de adelante y punteras
V_PAR = [('par completo', None), ('zapatilla en primer plano', ('z', (0.30, 0.0, 1.0, 1.0))), ('detalle de la puntera y la suela', ('z', (0.0, 0.32, 0.56, 1.0)))]

