EN = 'ENTRENAMIENTO/'


def zapatilla(id_, archivo, pub, nombre, precio, desc, car, espuma, placa, peso, drop, uso, color, extra=()):
    return dict(id=id_, src=archivo, cat='calzado', pub=pub, nombre=nombre, precio=precio, desc=desc, car=car,
                ficha=[['Amortiguación', espuma], ['Placa', placa], ['Peso', peso], ['Desnivel (drop)', drop], ['Uso ideal', uso], ['Color', color],
                       ['Tallas', '39 – 45 (EU)' if pub == 'Hombre' else '36 – 40 (EU), con medias tallas']],
                vistas=V_PAR, claves=list(extra), tallas=TALLAS_H if pub == 'Hombre' else TALLAS_M)


def objeto(id_, archivo, cat, nombre, precio, desc, car, ficha, vistas, extra=()):
    return dict(id=id_, src=archivo, cat=cat, pub=None, nombre=nombre, precio=precio, desc=desc, car=car, ficha=ficha, vistas=vistas, claves=list(extra), tallas=[])


